import { apiRequest } from "@/client";

export interface Subcategory{
    slug: string;
    name: string;
    category: Category[];
    
}
export interface Category{
    name: string;
    subCategories: Subcategory[]
}
export const couresAPI ={
    getMenu: async(): Promise<Category[]> =>{
        return apiRequest<Category[]>('/courses/menu')
    }
}